// app/_brand/og-assets.ts — pre-baked brand artwork for the favicon, the
// apple-touch icon, and the Open Graph / Twitter card (F16).
//
// These bytes are produced ahead of time and committed, never rendered per
// request: the routes that serve them (app/icon.tsx, app/apple-icon.tsx,
// app/opengraph-image.tsx, app/twitter-image.tsx) only decode and return them
// with a long-lived Cache-Control header. Keeping the artwork static is what
// lets those routes stay cheap on Cloudflare's edge.
//
// The motif is the `.brand-mark` treatment from app/globals.css: the wordmark's
// "cd" initials in the mono face, framed by two accent rules above and below.
// Colours are the palette tokens --cd-canvas (#0b1110), --cd-accent (#64dfa6),
// --cd-text (#f0f6f2) and --cd-muted (#96aa9e).
//
// To regenerate, re-render at the same dimensions and replace the base64
// constants below. The favicon is deliberately left as SVG so it stays sharp at
// any size and carries no raster payload.

export const ICON_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" width=\"32\" height=\"32\" role=\"img\" aria-label=\"CyberDaily\">\n  <rect width=\"32\" height=\"32\" rx=\"6\" fill=\"#0b1110\"/>\n  <rect x=\"7\" y=\"5\" width=\"18\" height=\"2.5\" fill=\"#64dfa6\"/>\n  <rect x=\"7\" y=\"24.5\" width=\"18\" height=\"2.5\" fill=\"#64dfa6\"/>\n  <text x=\"16\" y=\"21\" text-anchor=\"middle\" fill=\"#64dfa6\"\n        font-family=\"ui-monospace, SFMono-Regular, Menlo, Consolas, monospace\"\n        font-size=\"13\" font-weight=\"600\" letter-spacing=\"0.5\">cd</text>\n</svg>";

/** 180x180 PNG, base64 — apple-touch-icon for iOS home-screen bookmarks. */
export const APPLE_ICON_PNG_BASE64 =
  "";

/** 1200x630 PNG, base64 — the Open Graph / Twitter card artwork. */
export const OG_IMAGE_PNG_BASE64 =
  "";

/**
 * Decode a base64 string to bytes.
 *
 * Written against Web APIs only (`atob`, `Uint8Array`) rather than Node's
 * Buffer, because every route that calls it runs on the edge runtime, where
 * Buffer is not guaranteed to exist.
 *
 * The array is built over an explicit `ArrayBuffer` so the return type is
 * `Uint8Array<ArrayBuffer>` rather than `Uint8Array<ArrayBufferLike>`. Since
 * TypeScript 5.7 the typed arrays are generic in their buffer, and `BodyInit`
 * accepts only the `ArrayBuffer` form — the looser one would also admit a
 * `SharedArrayBuffer`, which `Response` cannot take. Passing the result
 * straight to `new Response(...)` does not type-check without this.
 */
export function base64ToBytes(base64: string): Uint8Array<ArrayBuffer> {
  const binary = atob(base64);
  const buffer = new ArrayBuffer(binary.length);
  const bytes = new Uint8Array(buffer);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
